var get_turns = (context, u2) => {
    let turns = context
       .split("\n")
       .filter(line => line.trim().startsWith("u"))
       .map(line => line.trim().replace("u", ""))
       .map((u2_reply, i) => {
            if (i === 0) return null;
            let preceding_u2 = turns[i - 1].u2;
            let preceding_message = context.split("\n").find(line => line.includes(preceding_u2));
            let user = preceding_message.includes("best_friend")? "Steve" : "u1";
            return {
                [user]: preceding_message.trim().replace(`${preceding_u2} `, ""),
                u2: u2_reply
            }
        })
       .filter(turn => turn!== null);
    return {
        "turns": turns
    }
};

